def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The full-height 2 column is the divider; the most common other color
    # is the background.
    divider = next(c for c in range(w) if all(grid[r][c] == 2 for r in range(h)))
    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]
    if not cells:
        return out

    min_c = min(c for r, c, v in cells)
    max_c = max(c for r, c, v in cells)

    # Erase the object at its original location.
    for r, c, v in cells:
        out[r][c] = background

    # Move it next to the divider, preserving its shape, then draw the 8 line.
    shift = divider + 1 - min_c
    for r, c, v in cells:
        out[r][c + shift] = v

    line_col = max_c + shift + 1
    if line_col < w:
        for r in range(h):
            out[r][line_col] = 8

    return out
